"""Document model and corpus loading helpers."""

from __future__ import annotations

import json
from dataclasses import dataclass, field
from typing import Any, Dict, List


@dataclass
class Document:
    """A retrievable text unit carrying metadata used for filtering and ranking."""

    id: str
    text: str
    metadata: Dict[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        if not self.id:
            raise ValueError("Document.id must be a non-empty string")
        if not isinstance(self.text, str) or not self.text.strip():
            raise ValueError("Document.text must be a non-empty string")


def load_corpus(path: str) -> List[Document]:
    """Load documents from a JSON file (list of {id, text, metadata})."""
    with open(path, "r", encoding="utf-8") as fh:
        raw = json.load(fh)
    if not isinstance(raw, list):
        raise ValueError("Corpus file must contain a JSON list")
    docs: List[Document] = []
    for i, item in enumerate(raw):
        docs.append(
            Document(
                id=str(item.get("id", f"doc-{i}")),
                text=str(item["text"]),
                metadata=dict(item.get("metadata", {})),
            )
        )
    return docs

"""Metadata filtering, hybrid retrieval, and metadata-aware ranking.

Retrieval pipeline
------------------
1. ``MetadataFilter`` narrows the search space using declarative filters.
2. ``HybridRetriever`` gathers candidate documents from dense and sparse
   evidence over the filtered set (union of stage-1 top-k lists).
3. ``MetadataRanker`` fuses dense similarity, BM25 lexical relevance and a
   metadata quality score (recency, source authority, query/metadata token
   matches) into a single relevance score.
4. ``Reranker`` optionally applies reciprocal-rank fusion or a cross-encoder
   as a post-retrieval refinement step.
"""

from __future__ import annotations

import collections
import re
import warnings
from dataclasses import dataclass, field
from datetime import date, datetime
from typing import Any, Dict, List, Optional, Sequence, Tuple

from .documents import Document
from .embeddings import BM25Index, DenseEmbedder, tokenize


def _parse_date(value: str) -> date:
    """Parse ISO-8601 dates and datetimes into ``date`` objects."""
    try:
        return datetime.fromisoformat(value).date()
    except ValueError:
        return date.fromisoformat(value)


def _cosine(a: Sequence[float], b: Sequence[float]) -> float:
    """Cosine similarity (works for L2-normalized vectors)."""
    return sum(x * y for x, y in zip(a, b))


def _minmax(value: float, lo: float, hi: float) -> float:
    """Min-max normalization; neutral 0.5 when the range is degenerate."""
    if hi > lo:
        return (value - lo) / (hi - lo)
    return 0.5


# ---------------------------------------------------------------------------
# Metadata filtering
# ---------------------------------------------------------------------------


class MetadataFilter:
    """Declarative metadata filter (all top-level keys combine with AND).

    Supported conditions:

    Equality / membership::

        {"category": "billing"}                      # exact match
        {"category": {"$in": ["billing", "api"]}}    # any-of
        {"category": {"$nin": ["billing"]}}          # none-of
        {"category": {"$ne": "billing"}}             # not equal
        {"tags": {"$contains": "security"}}          # list/str contains
        {"tags": {"$contains": ["sso", "mfa"]}}      # contains all

    Comparison (numbers, or ISO-8601 date strings)::

        {"date": {"$gte": "2024-06-01", "$lt": "2025-01-01"}}
        {"priority": {"$lte": 3}}

    Existence / regex::

        {"source": {"$exists": True}}
        {"source": {"$regex": r"docs\\\\.acme\\\\.com"}}

    Example::

        MetadataFilter({"category": "security", "date": {"$gte": "2024-01-01"}})
    """

    _OPS = frozenset(
        {
            "$eq",
            "$ne",
            "$in",
            "$nin",
            "$gt",
            "$gte",
            "$lt",
            "$lte",
            "$contains",
            "$exists",
            "$regex",
        }
    )
    _COMPARATORS = {
        "$gt": lambda a, b: a > b,
        "$gte": lambda a, b: a >= b,
        "$lt": lambda a, b: a < b,
        "$lte": lambda a, b: a <= b,
    }

    def __init__(self, spec: Optional[Dict[str, Any]] = None):
        self.spec = dict(spec or {})
        self._validate()

    def _validate(self) -> None:
        for key, cond in self.spec.items():
            if isinstance(cond, dict) and not set(cond).isdisjoint(self._OPS):
                unknown = set(cond) - self._OPS
                if unknown:
                    raise ValueError(
                        f"Unknown metadata operators for field {key!r}: {sorted(unknown)}"
                    )

    # -- operator implementations ------------------------------------------
    @staticmethod
    def _apply(op: str, field_value: Any, arg: Any) -> bool:
        if op == "$eq":
            return field_value == arg
        if op == "$ne":
            return field_value != arg
        if op == "$in":
            return field_value in arg
        if op == "$nin":
            return field_value not in arg
        if op in MetadataFilter._COMPARATORS:
            try:
                return MetadataFilter._COMPARATORS[op](field_value, arg)
            except TypeError:
                return MetadataFilter._COMPARATORS[op](str(field_value), str(arg))
        if op == "$contains":
            if isinstance(field_value, str):
                if isinstance(arg, (list, tuple, set)):
                    return all(str(a) in field_value for a in arg)
                return str(arg) in field_value
            values = field_value if isinstance(field_value, (list, tuple, set)) else [field_value]
            if isinstance(arg, (list, tuple, set)):
                return all(a in values for a in arg)
            return arg in values
        if op == "$exists":
            return (field_value is not None) == bool(arg)
        if op == "$regex":
            return re.search(str(arg), str(field_value or "")) is not None
        raise ValueError(f"Unsupported metadata operator: {op}")

    def matches(self, metadata: Dict[str, Any]) -> bool:
        """True if ``metadata`` satisfies every condition in the spec."""
        for key, cond in self.spec.items():
            field_value = metadata.get(key)
            if isinstance(cond, dict) and not set(cond).isdisjoint(self._OPS):
                for op, arg in cond.items():
                    if not self._apply(op, field_value, arg):
                        return False
            elif isinstance(cond, dict):
                # Bare dict (no operators) requires full dict equality.
                if field_value != cond:
                    return False
            else:
                if field_value != cond:
                    return False
        return True

    def __repr__(self) -> str:  # pragma: no cover - convenience
        return f"MetadataFilter({self.spec!r})"


# ---------------------------------------------------------------------------
# Retrieval results
# ---------------------------------------------------------------------------


@dataclass
class ScoredDocument:
    """A retrieved document with per-component and fused relevance scores."""

    document: Document
    dense_score: float = 0.0
    sparse_score: float = 0.0
    metadata_score: float = 0.0
    final_score: float = 0.0
    rank: int = 0
    breakdown: Dict[str, float] = field(default_factory=dict)

    @property
    def id(self) -> str:
        return self.document.id

    def __repr__(self) -> str:  # pragma: no cover - convenience
        return (
            f"ScoredDocument(id={self.document.id!r}, final={self.final_score:.3f}, "
            f"dense={self.dense_score:.3f}, sparse={self.sparse_score:.3f}, "
            f"metadata={self.metadata_score:.3f})"
        )


# ---------------------------------------------------------------------------
# Hybrid retrieval with metadata filtering
# ---------------------------------------------------------------------------


class HybridRetriever:
    """Two-stage hybrid retrieval with metadata filtering.

    Stage 1 gathers candidate documents: the union of the top-``stage1_k``
    dense hits and top-``stage1_k`` sparse (BM25) hits among documents that
    satisfy the metadata filter.
    """

    def __init__(
        self,
        dense: DenseEmbedder,
        bm25: BM25Index,
        documents: Sequence[Document],
        embeddings: Sequence[Sequence[float]],
        stage1_k: int = 50,
    ):
        if len(documents) != len(embeddings):
            raise ValueError("documents and embeddings must have the same length")
        self.dense = dense
        self.bm25 = bm25
        self.documents = list(documents)
        self.embeddings = list(embeddings)
        self.stage1_k = max(1, stage1_k)

    def filtered_indices(self, metadata_filter: Optional[MetadataFilter]) -> List[int]:
        if metadata_filter is None:
            return list(range(len(self.documents)))
        return [
            i
            for i, doc in enumerate(self.documents)
            if metadata_filter.matches(doc.metadata)
        ]

    def candidates(
        self,
        query: str,
        metadata_filter: Optional[MetadataFilter] = None,
    ) -> Dict[int, Tuple[float, float]]:
        """Return ``{doc_index: (dense_score, sparse_score)}`` for candidates."""
        indices = self.filtered_indices(metadata_filter)
        if not indices:
            return {}

        query_vec = self.dense.embed(query)
        dense_ranked = sorted(
            ((i, _cosine(query_vec, self.embeddings[i])) for i in indices),
            key=lambda p: p[1],
            reverse=True,
        )
        top_dense = dict(dense_ranked[: self.stage1_k])

        query_tokens = tokenize(query)
        top_sparse: Dict[int, float] = {}
        if query_tokens:
            sparse_ranked = sorted(
                ((i, self.bm25.score(query_tokens, i)) for i in indices),
                key=lambda p: p[1],
                reverse=True,
            )
            top_sparse = dict(sparse_ranked[: self.stage1_k])

        candidates: Dict[int, Tuple[float, float]] = {}
        for i in indices:
            if i in top_dense or i in top_sparse:
                candidates[i] = (top_dense.get(i, 0.0), top_sparse.get(i, 0.0))
        return candidates


# ---------------------------------------------------------------------------
# Metadata-aware ranking
# ---------------------------------------------------------------------------


class MetadataRanker:
    """Metadata-aware relevance ranking.

    Fused score::

        final = w_dense * norm(dense) + w_sparse * norm(sparse) + w_meta * metadata_score

    The metadata score blends (weights sum to 1 by default):

    * recency -- corpus-relative date position (newest = 1.0);
    * authority -- source tier from ``authority_map`` or ``priority``
      (1 = highest authority ... 5 = lowest);
    * query_match -- fraction of distinct query tokens found in metadata
      fields such as ``title``, ``category``, ``tags``, ``source``.

    Parameters
    ----------
    dense_weight, sparse_weight, metadata_weight: fusion weights.
    authority_map: {source string: score in [0, 1]}.
    query_match_fields: metadata keys inspected for query-token overlap.
    recency_weight, authority_weight, query_match_weight: metadata blend weights.
    """

    def __init__(
        self,
        dense_weight: float = 0.45,
        sparse_weight: float = 0.30,
        metadata_weight: float = 0.25,
        authority_map: Optional[Dict[str, float]] = None,
        query_match_fields: Sequence[str] = ("title", "category", "tags", "source"),
        recency_weight: float = 0.40,
        authority_weight: float = 0.30,
        query_match_weight: float = 0.30,
    ):
        self.dense_weight = dense_weight
        self.sparse_weight = sparse_weight
        self.metadata_weight = metadata_weight
        self.authority_map = dict(authority_map or {})
        self.query_match_fields = tuple(query_match_fields)
        self.recency_weight = recency_weight
        self.authority_weight = authority_weight
        self.query_match_weight = query_match_weight
        self.date_bounds: Optional[Tuple[date, date]] = None

    def set_date_bounds(self, bounds: Optional[Tuple[date, date]]) -> None:
        """Set corpus date min/max for corpus-relative recency scoring."""
        self.date_bounds = bounds

    # -- metadata components ------------------------------------------------
    def _recency_score(self, doc: Document) -> float:
        raw = doc.metadata.get("date")
        if not raw or self.date_bounds is None:
            return 0.5
        try:
            value = _parse_date(str(raw))
        except (TypeError, ValueError):
            return 0.5
        lo, hi = self.date_bounds
        span = (hi - lo).days
        if span <= 0:
            return 1.0 if value >= hi else 0.5
        return max(0.0, min(1.0, (value - lo).days / span))

    def _authority_score(self, doc: Document) -> float:
        source = str(doc.metadata.get("source", ""))
        if source in self.authority_map:
            return float(self.authority_map[source])
        priority = doc.metadata.get("priority")
        if priority is not None:
            try:
                p = float(priority)
                if 1.0 <= p <= 5.0:
                    return 1.0 - (p - 1.0) / 4.0
            except (TypeError, ValueError):
                pass
        return 0.5

    def _query_match_score(self, query_tokens: Sequence[str], doc: Document) -> float:
        unique = set(query_tokens)
        if not unique:
            return 0.0
        matched = set()
        for field_name in self.query_match_fields:
            value = doc.metadata.get(field_name)
            if value is None:
                continue
            values = value if isinstance(value, (list, tuple, set)) else [value]
            for v in values:
                matched |= unique & set(tokenize(str(v)))
        return min(1.0, len(matched) / len(unique))

    def _metadata_score(self, query_tokens: Sequence[str], doc: Document) -> float:
        recency = self._recency_score(doc)
        authority = self._authority_score(doc)
        match = self._query_match_score(query_tokens, doc)
        total_weight = self.recency_weight + self.authority_weight + self.query_match_weight
        if total_weight <= 0:
            return 0.0
        return (
            self.recency_weight * recency
            + self.authority_weight * authority
            + self.query_match_weight * match
        ) / total_weight

    # -- fusion -------------------------------------------------------------
    def score(
        self,
        query_tokens: Sequence[str],
        doc: Document,
        dense_score: float,
        sparse_score: float,
        dense_min: float,
        dense_max: float,
        sparse_min: float,
        sparse_max: float,
    ) -> Tuple[float, Dict[str, float]]:
        """Return ``(final_score, breakdown)`` for one candidate."""
        dense_n = _minmax(dense_score, dense_min, dense_max)
        sparse_n = _minmax(sparse_score, sparse_min, sparse_max)
        metadata_n = self._metadata_score(query_tokens, doc)
        final = (
            self.dense_weight * dense_n
            + self.sparse_weight * sparse_n
            + self.metadata_weight * metadata_n
        )
        breakdown = {
            "dense": round(dense_n, 4),
            "sparse": round(sparse_n, 4),
            "metadata": round(metadata_n, 4),
        }
        return final, breakdown


# ---------------------------------------------------------------------------
# Post-retrieval reranking
# ---------------------------------------------------------------------------


class Reranker:
    """Post-retrieval reranking.

    Methods
    -------
    ``fused`` (default)
        Keep the metadata-aware fused scores from :class:`MetadataRanker`.
    ``rrf``
        Reciprocal rank fusion over the dense-, sparse- and metadata-ranked
        lists (robust to score-scale differences).
    ``cross_encoder``
        Optional ``sentence-transformers`` CrossEncoder rerank. Falls back to
        ``fused`` when the model cannot be loaded.
    """

    RRF_K = 60

    def __init__(self, method: str = "fused", cross_encoder_model: Optional[str] = None):
        if method not in {"fused", "rrf", "cross_encoder"}:
            raise ValueError(f"Unknown rerank method: {method!r}")
        self.method = method
        self._cross_encoder = None
        if method == "cross_encoder" and cross_encoder_model:
            try:
                from sentence_transformers import CrossEncoder  # type: ignore

                self._cross_encoder = CrossEncoder(cross_encoder_model)
            except Exception as exc:  # pragma: no cover - optional dependency
                warnings.warn(
                    f"Could not load cross-encoder {cross_encoder_model!r} "
                    f"({exc}); falling back to fused ranking.",
                    RuntimeWarning,
                )
                self.method = "fused"

    def rerank(
        self,
        query: str,
        scored: Sequence[ScoredDocument],
        k: Optional[int] = None,
    ) -> List[ScoredDocument]:
        if not scored:
            return []
        if self.method == "rrf":
            ordered = self._rrf(scored)
        elif self.method == "cross_encoder" and self._cross_encoder is not None:
            ordered = self._cross_encoder_rerank(query, scored)
        else:
            ordered = sorted(scored, key=lambda s: s.final_score, reverse=True)
        for i, item in enumerate(ordered, start=1):
            item.rank = i
        return ordered[:k] if k else ordered

    def _rrf(self, scored: Sequence[ScoredDocument]) -> List[ScoredDocument]:
        lists = [
            sorted(scored, key=lambda s: s.dense_score, reverse=True),
            sorted(scored, key=lambda s: s.sparse_score, reverse=True),
            sorted(scored, key=lambda s: s.metadata_score, reverse=True),
        ]
        fused: Dict[str, float] = collections.defaultdict(float)
        for ranked_list in lists:
            for pos, item in enumerate(ranked_list, start=1):
                fused[item.document.id] += 1.0 / (self.RRF_K + pos)
        for item in scored:
            item.final_score = fused[item.document.id]
        return sorted(scored, key=lambda s: s.final_score, reverse=True)

    def _cross_encoder_rerank(
        self, query: str, scored: Sequence[ScoredDocument]
    ) -> List[ScoredDocument]:
        pairs = [[query, item.document.text] for item in scored]
        scores = self._cross_encoder.predict(pairs)
        for item, score in zip(scored, scores):
            item.final_score = float(score)
        return sorted(scored, key=lambda s: s.final_score, reverse=True)

"""Grounded answer generation with citations."""

from __future__ import annotations

import os
import re
import warnings
from dataclasses import dataclass, field
from typing import Callable, List, Optional, Sequence, Tuple

from .documents import Document
from .embeddings import tokenize
from .retrieval import ScoredDocument

_SENTENCE_SPLIT = re.compile(r"(?<=[.!?])\s+|\n+")


def _split_sentences(text: str) -> List[str]:
    return [part.strip() for part in _SENTENCE_SPLIT.split(text) if part.strip()]


@dataclass
class Answer:
    """A grounded answer with its supporting citations."""

    text: str
    citations: List[Document] = field(default_factory=list)
    confidence: float = 0.0
    grounded: bool = True

    def render(self) -> str:
        """Human-readable rendering including citation metadata."""
        lines = [self.text, ""]
        for i, doc in enumerate(self.citations, start=1):
            meta = ", ".join(f"{k}={v}" for k, v in doc.metadata.items())
            lines.append(f"[{i}] {doc.id} ({meta})")
        return "\n".join(lines)


class AnswerGenerator:
    """Generates grounded answers from ranked retrieved documents.

    The default strategy is extractive and dependency-free: sentences from the
    top-ranked documents that overlap with query terms are assembled into an
    answer, each tagged with a citation marker ``[rank]``.

    To use an LLM instead, set ``USE_LLM=1`` and ``OPENAI_API_KEY``; the LLM
    receives the ranked context (with citation headers) and is instructed to
    answer strictly from that context.
    """

    def __init__(self, max_context_chars: int = 4000, max_sentences: int = 3):
        self.max_context_chars = max_context_chars
        self.max_sentences = max_sentences

    # -- public -------------------------------------------------------------
    def generate(self, query: str, scored: Sequence[ScoredDocument]) -> Answer:
        llm = self._maybe_llm()
        if llm is not None:
            context = self._build_context(scored)
            text = llm(query, context)
            return Answer(
                text=text,
                citations=[s.document for s in scored],
                confidence=0.9,  # LLM path uses a grounding prompt
                grounded=True,
            )
        return self._extractive(query, scored)

    # -- LLM path -----------------------------------------------------------
    def _maybe_llm(self) -> Optional[Callable[[str, str], str]]:
        if os.environ.get("USE_LLM") != "1":
            return None
        api_key = os.environ.get("OPENAI_API_KEY")
        if not api_key:
            warnings.warn("USE_LLM=1 requires OPENAI_API_KEY; using extractive fallback.")
            return None
        try:
            from openai import OpenAI  # type: ignore
        except ImportError:
            warnings.warn("USE_LLM=1 requires the 'openai' package; using extractive fallback.")
            return None

        client = OpenAI(api_key=api_key)
        model = os.environ.get("OPENAI_MODEL", "gpt-4o-mini")

        def llm(query: str, context: str) -> str:
            response = client.chat.completions.create(
                model=model,
                temperature=0,
                messages=[
                    {
                        "role": "system",
                        "content": (
                            "You are a grounded research assistant. Answer the user's "
                            "question using ONLY the context provided below. Cite sources "
                            "inline as [1], [2], etc. If the context does not contain the "
                            "answer, say you do not have enough information."
                        ),
                    },
                    {
                        "role": "user",
                        "content": f"Context:\n{context}\n\nQuestion: {query}\n\nAnswer:",
                    },
                ],
            )
            return response.choices[0].message.content

        return llm

    def _build_context(self, scored: Sequence[ScoredDocument]) -> str:
        parts = []
        for i, item in enumerate(scored, start=1):
            doc = item.document
            header = (
                f"[{i}] id={doc.id} source={doc.metadata.get('source', 'unknown')} "
                f"date={doc.metadata.get('date', '?')} score={item.final_score:.3f}"
            )
            text = doc.text
            budget = max(200, self.max_context_chars // max(1, len(scored)))
            if len(text) > budget:
                text = text[:budget].rstrip() + " ..."
            parts.append(f"{header}\n{text}")
        return "\n\n".join(parts)

    # -- extractive path ----------------------------------------------------
    def _extractive(self, query: str, scored: Sequence[ScoredDocument]) -> Answer:
        query_tokens = set(tokenize(query))
        citations_all = [s.document for s in scored]
        if not query_tokens:
            return Answer(
                text="I don't have enough information in the retrieved documents to answer this query.",
                citations=citations_all,
                confidence=0.0,
                grounded=False,
            )

        evidence: List[Tuple[int, int, int, str, str]] = []
        for rank, item in enumerate(scored, start=1):
            for sentence in _split_sentences(item.document.text):
                overlap = len(query_tokens & set(tokenize(sentence)))
                if overlap > 0:
                    evidence.append((overlap, len(evidence), rank, item.document.id, sentence))

        evidence.sort(key=lambda e: (-e[0], e[1]))
        selected = evidence[: self.max_sentences]
        if not selected:
            return Answer(
                text="I don't have enough information in the retrieved documents to answer this query.",
                citations=citations_all,
                confidence=0.0,
                grounded=False,
            )

        matched_tokens = set()
        lines = []
        for _overlap, _order, rank, _doc_id, sentence in selected:
            matched_tokens |= query_tokens & set(tokenize(sentence))
            lines.append(f"- {sentence} [{rank}]")

        seen_ids = set()
        citations = []
        for _overlap, _order, rank, doc_id, _sentence in selected:
            if doc_id not in seen_ids:
                seen_ids.add(doc_id)
                citations.append(scored[rank - 1].document)

        confidence = min(1.0, 0.5 + 0.5 * len(matched_tokens) / len(query_tokens))
        return Answer(
            text="Based on the retrieved documents:\n" + "\n".join(lines),
            citations=citations,
            confidence=round(confidence, 3),
            grounded=True,
        )

